<?php
declare(strict_types=1);
function mcpOAuthBase(): string {$ep=agentMcpEndpoint();if(!$ep['url'])fail(503,'Die öffentliche MCP-Adresse ist noch nicht eingerichtet.');return substr($ep['url'],0,-5);}
function mcpOAuthMetadata(bool $resource): array {$base=mcpOAuthBase();return $resource?['resource'=>$base.'/mcp/','authorization_servers'=>[$base],'scopes_supported'=>['db:read','db:write'],'bearer_methods_supported'=>['header']]:['issuer'=>$base,'authorization_endpoint'=>$base.'/oauth/authorize/','token_endpoint'=>$base.'/oauth/token/','registration_endpoint'=>$base.'/oauth/register/','revocation_endpoint'=>$base.'/oauth/revoke/','response_types_supported'=>['code'],'grant_types_supported'=>['authorization_code','refresh_token'],'token_endpoint_auth_methods_supported'=>['none'],'code_challenge_methods_supported'=>['S256'],'scopes_supported'=>['db:read','db:write'],'authorization_response_iss_parameter_supported'=>true];}
function mcpOAuthRedirect(string $uri): string {
    $p=parse_url($uri);if(!$p||strlen($uri)>1000||($p['scheme']??'')!=='https'||isset($p['user'])||isset($p['pass'])||isset($p['port'])||isset($p['query'])||isset($p['fragment']))fail(422,'Nicht unterstützte OAuth-Rücksprungadresse.');$host=$p['host']??'';$path=$p['path']??'';
    $ok=$host==='chatgpt.com'&&($path==='/connector_platform_oauth_redirect'||preg_match('~^/connector/oauth/[a-zA-Z0-9_-]{8,120}$~D',$path));$ok=$ok||in_array($uri,['https://claude.ai/api/mcp/auth_callback','https://claude.com/api/mcp/auth_callback'],true);if(!$ok)fail(422,'Dieser MCP unterstützt OAuth für ChatGPT und Claude. Die Rücksprungadresse wurde nicht erkannt.');return $uri;
}
function mcpOAuthRegister(array $d): array {
    if(($d['token_endpoint_auth_method']??'none')!=='none'||array_diff(labList($d['grant_types']??['authorization_code','refresh_token'],2),['authorization_code','refresh_token'])||array_diff(labList($d['response_types']??['code'],1),['code']))fail(422,'Nur öffentliche OAuth-Clients mit PKCE werden unterstützt.');$redirects=labList($d['redirect_uris']??[],4);if(!$redirects)fail(422,'redirect_uris fehlt.');foreach($redirects as &$redirect){if(!is_string($redirect))fail(422,'Ungültige Rücksprungadresse.');$redirect=mcpOAuthRedirect($redirect);}unset($redirect);$name=studioText($d['client_name']??'KI-Client',120);$id='ectro_client_'.bin2hex(random_bytes(16));if((int)query('SELECT COUNT(*) FROM mcp_oauth_clients')->fetchColumn()>=5000)fail(429,'Zu viele registrierte Clients. Bitte die Administration informieren.');query('INSERT INTO mcp_oauth_clients VALUES(?,?,?,?)',[$id,$name,json_encode(array_values(array_unique($redirects))),time()]);return ['client_id'=>$id,'client_id_issued_at'=>time(),'client_name'=>$name,'redirect_uris'=>$redirects,'token_endpoint_auth_method'=>'none','grant_types'=>['authorization_code','refresh_token'],'response_types'=>['code']];
}
function mcpOAuthRequest(array $d): array {
    $cid=studioText($d['client_id']??'',100);$client=one('SELECT * FROM mcp_oauth_clients WHERE id=?',[$cid]);if(!$client)fail(422,'Unbekannter OAuth-Client. Verbindung in ChatGPT neu anlegen.');$redirect=studioText($d['redirect_uri']??'',1000);if(!in_array($redirect,json_decode($client['redirects'],true),true))fail(422,'Die Rücksprungadresse passt nicht zum registrierten Client.');if(($d['response_type']??'')!=='code'||($d['code_challenge_method']??'')!=='S256')fail(422,'Autorisierungscode mit PKCE S256 erforderlich.');$challenge=studioText($d['code_challenge']??'',43);if(!preg_match('/^[a-zA-Z0-9_-]{43}$/D',$challenge))fail(422,'Ungültige PKCE-Prüfung.');$resource=studioText($d['resource']??'',400);if($resource!==mcpOAuthBase().'/mcp/')fail(422,'Der angefragte MCP-Bereich stimmt nicht überein.');$scope=trim(studioText($d['scope']??'db:read',100));$scopes=preg_split('/\s+/',trim($scope));if(!in_array('db:read',$scopes,true)||array_diff($scopes,['db:read','db:write']))fail(422,'Nur db:read und optional db:write werden unterstützt.');$scope=in_array('db:write',$scopes,true)?'db:read db:write':'db:read';$state=studioText($d['state']??'',1024);return ['client_id'=>$cid,'redirect'=>$redirect,'challenge'=>$challenge,'resource'=>$resource,'scope'=>$scope,'state'=>$state,'client'=>$client['name']];
}
function mcpOAuthUserProfile(array $u,?int $version=null): array {
    if(!$u['active']||$u['must_change_password'])fail(403,'Bitte zuerst den eigenen Zugang prüfen und gegebenenfalls das Passwort ändern.');agentMcpRights($u,true);$p=agentMcpProfile($u);if(!$p['enabled']||!json_decode($p['selection'],true)||($version!==null&&(int)$p['version']!==$version))fail(403,'Die MCP-Freigabe wurde geändert oder abgeschaltet. Bitte erneut verbinden.');$hash=agentMcpConnectionHash(agentMcpConnection($u,$p['project_id']));if(!hash_equals($p['connection_hash']??'',$hash))fail(403,'Die Datenbankverbindung wurde geändert. MCP neu konfigurieren.');return $p;
}
function mcpOAuthCode(array $u,array $request,int $profileVersion): string {
    $p=mcpOAuthUserProfile($u,$profileVersion);$scope=$request['scope']??'db:read';if(str_contains($scope,'db:write')){needFeature($u,'mcp_write');if(!agentMcpWrites($p))fail(403,'Keine persönliche Schreibfreigabe vorhanden.');}$code=bin2hex(random_bytes(32));query('DELETE FROM mcp_oauth_codes WHERE expires<?',[time()]);query('INSERT INTO mcp_oauth_codes(hash,user_id,client_id,redirect,challenge,resource,profile_version,auth_version,expires,scope) VALUES(?,?,?,?,?,?,?,?,?,?)',[hash('sha256',$code),$u['id'],$request['client_id'],$request['redirect'],$request['challenge'],$request['resource'],$profileVersion,$u['auth_version'],time()+120,$scope]);return $code;
}
function mcpOAuthGrantUser(array $grant): array {
    $u=one('SELECT * FROM users WHERE id=?',[$grant['user_id']]);if(!$u||(int)$u['auth_version']!==(int)$grant['auth_version']||$grant['revoked']||(int)$grant['expires']<=time()||$grant['resource']!==mcpOAuthBase().'/mcp/')fail(401,'Die KI-Verbindung ist abgelaufen oder widerrufen.');$p=mcpOAuthUserProfile($u,(int)$grant['profile_version']);if(!hash_equals($p['connection_hash']??'',$grant['connection_hash']))fail(401,'Die Datenbankfreigabe hat sich geändert.');if(!str_contains($grant['scope']??'db:read','db:write'))$p['write_selection']='{}';$p['write_allowed']=features($u)['mcp_write'];return [$u,$p];
}
function mcpOAuthToken(array $d): array {
    $type=studioEnum($d['grant_type']??null,['authorization_code','refresh_token']);$client=studioText($d['client_id']??'',100);if(!one('SELECT id FROM mcp_oauth_clients WHERE id=?',[$client]))fail(401,'invalid_client');$resource=studioText($d['resource']??'',400);if($resource!==mcpOAuthBase().'/mcp/')fail(422,'invalid_target');if(isset($d['scope'])&&(!is_string($d['scope'])||!in_array('db:read',preg_split('/\s+/',trim($d['scope'])),true)||array_diff(preg_split('/\s+/',trim($d['scope'])),['db:read','db:write'])))fail(422,'invalid_scope');
    // Return errors after committing revocations/one-time code consumption.
    $result=transaction(function()use($d,$client,$resource,$type){
        if($type==='authorization_code'){$code=studioText($d['code']??'',100);$c=one('SELECT * FROM mcp_oauth_codes WHERE hash=?',[hash('sha256',$code)]);if(!$c||(int)$c['expires']<=time()||$c['client_id']!==$client||$c['resource']!==$resource||$c['redirect']!==($d['redirect_uri']??''))return ['error'=>'invalid_grant'];$verifier=studioText($d['code_verifier']??'',128);if(!preg_match('/^[a-zA-Z0-9._~-]{43,128}$/D',$verifier)||!hash_equals($c['challenge'],rtrim(strtr(base64_encode(hash('sha256',$verifier,true)),'+/','-_'),'=')))return ['error'=>'invalid_grant'];query('DELETE FROM mcp_oauth_codes WHERE hash=?',[$c['hash']]);$u=one('SELECT * FROM users WHERE id=?',[$c['user_id']]);if(!$u||(int)$u['auth_version']!==(int)$c['auth_version'])return ['error'=>'invalid_grant'];try{$p=mcpOAuthUserProfile($u,(int)$c['profile_version']);}catch(ApiError){return ['error'=>'invalid_grant'];}$grant=['id'=>id(),'user_id'=>$u['id'],'client_id'=>$client,'profile_version'=>$p['version'],'auth_version'=>$u['auth_version'],'connection_hash'=>$p['connection_hash'],'resource'=>$resource,'refresh_hash'=>null,'expires'=>time()+30*86400,'revoked'=>0,'created'=>time(),'scope'=>$c['scope']??'db:read'];if(str_contains($grant['scope'],'db:write')&&!agentMcpWrites($p))return ['error'=>'invalid_grant'];if(isset($d['scope'])&&array_diff(preg_split('/\s+/',trim($d['scope'])),explode(' ',$grant['scope'])))return ['error'=>'invalid_scope'];query('INSERT INTO mcp_oauth_grants(id,user_id,client_id,profile_version,auth_version,connection_hash,resource,refresh_hash,expires,revoked,created,scope) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)',array_values($grant));}
        else{$refresh=studioText($d['refresh_token']??'',100);$hash=hash('sha256',$refresh);$grant=one('SELECT * FROM mcp_oauth_grants WHERE refresh_hash=?',[$hash]);if(!$grant){$used=one('SELECT g.* FROM mcp_oauth_refresh_used r JOIN mcp_oauth_grants g ON g.id=r.grant_id WHERE r.hash=?',[$hash]);if($used&&$used['client_id']===$client)query('UPDATE mcp_oauth_grants SET revoked=1 WHERE id=?',[$used['id']]);return ['error'=>'invalid_grant'];}if($grant['client_id']!==$client||$grant['resource']!==$resource)return ['error'=>'invalid_grant'];try{mcpOAuthGrantUser($grant);}catch(ApiError){return ['error'=>'invalid_grant'];}if(isset($d['scope'])&&array_diff(preg_split('/\s+/',trim($d['scope'])),explode(' ',$grant['scope']??'db:read')))return ['error'=>'invalid_scope'];query('INSERT INTO mcp_oauth_refresh_used VALUES(?,?)',[$hash,$grant['id']]);}
        if(isset($d['scope'])){$requested=preg_split('/\s+/',trim($d['scope']));$granted=explode(' ',$grant['scope']??'db:read');if(!in_array('db:read',$requested,true)||array_diff($requested,$granted))return ['error'=>'invalid_scope'];$grant['scope']=in_array('db:write',$requested,true)?'db:read db:write':'db:read';query('UPDATE mcp_oauth_grants SET scope=? WHERE id=?',[$grant['scope'],$grant['id']]);}
        $access='ectro_oauth_'.bin2hex(random_bytes(32));$refresh='ectro_refresh_'.bin2hex(random_bytes(32));query('UPDATE mcp_oauth_grants SET refresh_hash=? WHERE id=?',[hash('sha256',$refresh),$grant['id']]);query('INSERT INTO mcp_oauth_access VALUES(?,?,?)',[hash('sha256',$access),$grant['id'],time()+3600]);query('DELETE FROM mcp_oauth_access WHERE expires<?',[time()]);query('DELETE FROM mcp_oauth_grants WHERE expires<?',[time()]);return ['access_token'=>$access,'refresh_token'=>$refresh,'token_type'=>'Bearer','expires_in'=>3600,'scope'=>$grant['scope']??'db:read'];
    });if(isset($result['error']))fail(400,$result['error']);return $result;
}
function mcpOAuthAuthenticate(string $token): array {
    if(!preg_match('/^ectro_oauth_[a-f0-9]{64}$/D',$token))fail(401,'invalid_token');$access=one('SELECT * FROM mcp_oauth_access WHERE hash=?',[hash('sha256',$token)]);if(!$access||(int)$access['expires']<=time())fail(401,'invalid_token');$grant=one('SELECT * FROM mcp_oauth_grants WHERE id=?',[$access['grant_id']]);if(!$grant)fail(401,'invalid_token');$result=mcpOAuthGrantUser($grant);$result[1]['_oauth_grant']=$grant['id'];$result[1]['_oauth_access']=$access['hash'];return $result;
}
function mcpOAuthRevoke(array $d): void {
    $client=studioText($d['client_id']??'',100);$hash=hash('sha256',studioText($d['token']??'',100));$g=one('SELECT * FROM mcp_oauth_grants WHERE refresh_hash=?',[$hash]);if(!$g){$a=one('SELECT grant_id FROM mcp_oauth_access WHERE hash=?',[$hash]);$g=$a?one('SELECT * FROM mcp_oauth_grants WHERE id=?',[$a['grant_id']]):null;}if($g&&$g['client_id']===$client)query('UPDATE mcp_oauth_grants SET revoked=1 WHERE id=?',[$g['id']]);
}
function mcpOAuthConsentPage(string $title,string $body): never {
